// It returns an error if the edge is not defined in the schema.
func (m *Mutation) ResetEdge(name string) error {
	switch name {
	case EdgeTenant:
		m.ResetTenant()
		return nil
	}
	return fmt.Errorf("unknown Holder edge %s", name)
}
